fn binary_search<T: Ord>(items: &[T], target: &T) -> Option<usize> {
    let len = items.len();
    if len == 0 {
        return None;
    }
    let mut low = 0;
    let mut high = len;
    while low <= high {
        let mid = (low + high) / 2;
        if items[mid] == target {
            return Some(mid);
        } else if items[mid] < target {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    None
}
